CREATE TABLE IF NOT EXISTS stock_exceptions(id BIGINT AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,platform VARCHAR(40) NOT NULL,reference_no VARCHAR(100),txn_date DATE,before_qty INT,after_qty INT,opened_by INT,assigned_to INT NULL,reason TEXT NULL,correction_reference VARCHAR(100) NULL,status VARCHAR(20) DEFAULT 'Open',resolved_by INT NULL,resolved_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(status),INDEX(product_id,platform));
CREATE TABLE IF NOT EXISTS transaction_reversals(id BIGINT AUTO_INCREMENT PRIMARY KEY,source_type VARCHAR(20) NOT NULL,source_id BIGINT NOT NULL,reason TEXT NOT NULL,status VARCHAR(20) DEFAULT 'Pending',requested_by INT,approved_by INT NULL,result_json LONGTEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,approved_at DATETIME NULL,INDEX(source_type,source_id));
CREATE TABLE IF NOT EXISTS borrowed_items(id BIGINT AUTO_INCREMENT PRIMARY KEY,borrow_ref VARCHAR(100) UNIQUE,product_id INT NOT NULL,source_platform VARCHAR(40) NOT NULL,borrower VARCHAR(150) NOT NULL,qty INT NOT NULL,returned_qty INT DEFAULT 0,converted_qty INT DEFAULT 0,issue_date DATE,due_date DATE,status VARCHAR(30) DEFAULT 'Outstanding',reason TEXT,user_id INT,outflow_id BIGINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS borrowed_events(id BIGINT AUTO_INCREMENT PRIMARY KEY,borrow_id BIGINT NOT NULL,event_type VARCHAR(30),qty INT,good_qty INT DEFAULT 0,damaged_qty INT DEFAULT 0,reference_no VARCHAR(100) UNIQUE,status VARCHAR(20) DEFAULT 'Posted',reason TEXT,user_id INT,approved_by INT NULL,txn_date DATE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(borrow_id));
CREATE TABLE IF NOT EXISTS return_batches(id BIGINT AUTO_INCREMENT PRIMARY KEY,batch_ref VARCHAR(100) UNIQUE,status VARCHAR(30) DEFAULT 'Review',stored_path VARCHAR(255),filename VARCHAR(255),rows_json LONGTEXT NOT NULL,revision INT DEFAULT 1,created_by INT,approved_by INT NULL,posted_by INT NULL,posted_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS posted_returns(id BIGINT AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT NOT NULL,platform VARCHAR(40),return_id VARCHAR(100),original_ref VARCHAR(100) NULL,product_id INT,qty INT,good_qty INT,damaged_qty INT,borrow_id BIGINT NULL,txn_date DATE,user_id INT,dedupe_key CHAR(64) UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(platform,original_ref,product_id));
CREATE TABLE IF NOT EXISTS category_sequences(prefix VARCHAR(20) PRIMARY KEY,category_key VARCHAR(200) UNIQUE,next_number INT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS managed_categories(id INT AUTO_INCREMENT PRIMARY KEY,main_name VARCHAR(100),sub_name VARCHAR(100) DEFAULT '',active TINYINT DEFAULT 1,UNIQUE(main_name,sub_name));
CREATE TABLE IF NOT EXISTS process_reconciliations(id BIGINT AUTO_INCREMENT PRIMARY KEY,filename VARCHAR(255),stored_path VARCHAR(255),rows_json LONGTEXT,status VARCHAR(30) DEFAULT 'Review',revision INT DEFAULT 1,created_by INT,posted_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS process_backups(id BIGINT AUTO_INCREMENT PRIMARY KEY,backup_ref VARCHAR(100) UNIQUE,status VARCHAR(30),manifest_path VARCHAR(500),error_text TEXT,user_id INT NULL,restore_test_at DATETIME NULL,restore_test_status VARCHAR(30) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS day_closings(close_date DATE PRIMARY KEY,status VARCHAR(30),reason TEXT,closed_by INT,closed_at DATETIME,summary_json LONGTEXT);

CREATE TABLE IF NOT EXISTS stock_events(id BIGINT AUTO_INCREMENT PRIMARY KEY,txn_date DATE,platform VARCHAR(40),product_id INT,before_qty INT,after_qty INT,reference_no VARCHAR(100),action_type VARCHAR(60),user_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(txn_date),INDEX(product_id),INDEX(reference_no));
